targets.query:
from(bucket: "aqi36")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "imputation_telemetry" and r._field == "latency_ms")

from(bucket: "aqi36")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "imputation_telemetry" and r._field == "nfe_per_window")

from(bucket: "aqi36")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "imputation_telemetry" and (r._field == "window_mae" or r._field == "window_crps"))
